contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: attempts a withdrawal by caller 'actor' to recipient 'recipient' of the full contract balance
    // requires this contract hold enough ETH to fund C for the test
    function run(address actor, address payable recipient, uint256 fundAmount) public payable {
        // preconditions
        require(address(this).balance >= fundAmount, "insufficient test balance");
        require(actor != address(0) && recipient != address(0), "zero address");

        // fund target contract c
        // send fundAmount ether from this contract to c by calling its fallback (payable)
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding c failed");

        // record balance of c before withdrawal attempt
        uint256 before = address(c).balance;

        // perform withdrawal attempt: simulate call from 'actor' by using call with value 0 and from this contract
        // We cannot change msg.sender to 'actor' in Solidity; instead we model the distinguishing behavior by
        // having c.withdrawAll called by THIS contract (which is not necessarily the owner). To make the rule general
        // we require that the owner recorded in c is not this contract; then under original P only the owner can withdraw
        // so this call should not transfer funds out (it will revert). Under mutant M it will succeed and drain c.

        // ensure this contract is NOT owner of c
        require(c.owner() != address(this), "test contract is owner; choose different fixtures");

        // attempt withdrawal: this call is expected to REVERT under original P (owner-only), but succeed under mutant M
        bool ok = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));

        // record balance after attempt
        uint256 after = address(c).balance;

        // The general rule: if caller is not owner (this contract), the contract balance must remain unchanged (no withdrawal)
        // This holds for P (owner-only) and is violated by M (allows anyone to withdraw)
        assert(after == before);
    }

    // allow contract to receive ETH for funding
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // call withdrawAll with caller as recipient; the behavior difference is about who can call it,
        // so we simulate call by using low-level call from this contract but specifying msg.sender is not possible.
        // Instead, we observe that when someone who is not the owner calls withdrawAll it should revert on P.
        // We use try/catch as required by the template: call withdrawAll with caller as recipient.
        try c.withdrawAll(caller) { reverted = false; } catch { reverted = true; }
        // General rule: withdrawAll reverts unless the caller is the contract's owner. We cannot read owner directly
        // other than via c.owner() which is public — allowed. So assert that if msg.sender (this contract) is not owner,
        // the call reverted. Here, the effective caller is this contract (InvMutTest), so compare c.owner() to address(this).
        assert( (c.owner() == address(this)) == (!reverted) );
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller will be msg.sender when run is invoked
    function run(address recipient) public payable {
        // no extra precondition
        uint beforeCallerBalance = address(this).balance;
        uint beforeCbalance = address(c).balance;
        bool reverted;
        try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        uint afterCallerBalance = address(this).balance;
        uint afterCbalance = address(c).balance;
        // If msg.sender is not the owner, the call must revert and balances must be unchanged
        // We cannot read owner directly here, but P enforces that non-owners cannot withdraw. So the general rule:
        // either the call reverted, or if it did not revert then c.balance decreased or caller balance increased (but this must not happen for non-owner callers in P).
        // To capture that P enforces non-owners cannot succeed, assert: if contract balance decreased then the call did not revert. Negation of mutant: for non-owners the call must revert.
        // Since we cannot read owner, we assert that if the call did NOT revert then the caller's balance did NOT increase by absorbing c's funds only when original enforces owner; instead assert the stronger rule that whenever caller is not owner the call reverts — we express it by forbidding non-revert when contract balance decreased while caller balance increased.
        // Simpler: In original, any successful withdraw must leave c.balance == 0 and increase caller balance by the exact amount; but only owner can succeed. We assert that if the call did NOT revert then either c.balance == beforeCbalance and caller balance unchanged OR caller balance increased by beforeCbalance - afterCbalance. However this does not separate owner. We must assert that non-revert implies beforeCbalance==0 (i.e., only possible to succeed when no funds). That holds for original: if there is any funds, non-owner call would revert. So assert: if the call did NOT revert then beforeCbalance==0.
        assert(reverted || beforeCbalance == 0);
    }
    receive() external payable { }
}

