pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: attacker is a candidate caller (may be owner or not), fundAmount is the Ether sent to C
    function testFuzz_property(address attacker, uint256 fundAmount) public {
        // keep fundAmount in a reasonable range but wide
        fundAmount = bound(fundAmount, 0, 1 ether);

        // ensure attacker is not the zero address (admissible) but allow it too; keep wide
        vm.assume(attacker != address(0));

        // Fund the attacker so it can send Ether into C if needed (not strictly necessary but general)
        vm.deal(attacker, fundAmount);

        // Send some Ether into the contract c so there is something to withdraw
        if (fundAmount > 0) {
            vm.prank(attacker);
            (bool sent, ) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        // Record balance before withdraw
        uint256 before = address(c).balance;

        // Try to have 'attacker' call withdrawAll to recipient = attacker
        bool ok;
        vm.prank(attacker);
        try c.withdrawAll(attacker) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, check contract balance
        uint256 after = address(c).balance;

        // GENERAL ASSERTION: If the caller is NOT the owner, then the reference contract C will NOT allow that caller
        // to drain the contract balance (i.e., after == before). This is the single assertTrue that the correct
        // contract satisfies for all inputs; the mutant removing the owner check will allow some non-owner caller to
        // make after == 0 while before > 0, violating the rule.
        if (attacker != address(this)) {
            // For non-owner callers, the reference contract requires the call to either revert or leave balance unchanged.
            // So in all admissible inputs we must have after == before.
            assertTrue(after == before);
        } else {
            // If attacker is the owner (address(this)), the owner is allowed to withdraw; no invariant to assert here
            // that would distinguish the mutant, so just assert a tautology reading c to satisfy single-assert requirement.
            // Use address(c).balance >= 0 which always holds.
            assertTrue(address(c).balance >= 0);
        }
    }
}

