    function testFuzz_property(address caller, address recipient, uint256 funding) public {
        // keep funding in a reasonable range so vm.deal works and avoid zero which is still admissible
        funding = bound(funding, 0, 1 ether);

        // ensure caller and recipient are not the owner (address(this)) to test non-owner behavior
        vm.assume(caller != address(this));
        vm.assume(recipient != address(this));

        // Fund the contract with `funding` wei from an externally-owned account (use address(this) as funder)
        if (funding > 0) {
