        vm.prank(caller);
        // attempt withdrawal to caller
        try c.withdrawAll(caller) {
            // call succeeded, proceed
        } catch {
            // if it reverts, that's fine; still shouldn't allow balance to become zero unless caller==owner
        }

        // Exactly one assertion: if caller is owner (address(this)) then c may be drained to zero;
