contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Send Ether to this test contract so it can forward to c when needed
    receive() external payable {}

    // Single public function with all test logic
    // Params: caller - address that will be the owner/caller of withdrawAll on c
    //         recipient - intended recipient passed into withdrawAll
    //         fundAmount - amount of wei to send into c before withdrawal
    function run(address payable caller, address payable recipient, uint256 fundAmount) public {
        // Precondition: this contract must have enough balance to fund c
        require(address(this).balance >= fundAmount, "insufficient test balance");
        // Fund target contract c by sending Ether to its fallback
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok, "funding failed");

        // Ensure caller is the owner by checking c.owner() equals caller
        // The test requires that caller is owner; if not, nothing meaningful about transfer can be asserted
        require(c.owner() == caller, "caller must be owner");

        // Simulate caller invoking withdrawAll(recipient)
        // We perform the call from this contract but emulate msg.sender==caller by using low-level call with from not possible in Solidity tests.
        // Instead we require that caller equals address(this) for the test run so that calling directly matches msg.sender.
        // Enforce that caller is this contract to allow direct invocation as owner.
        require(caller == address(this), "caller must be this contract for direct call");

        // Now call withdrawAll with the provided recipient
        c.withdrawAll(recipient);

        // After withdrawal, entire balance of c should be transferred to the provided recipient
        // i.e., address(c).balance == 0 and recipient's balance increased by fundAmount.
        // We can only observe address(c).balance and address(this).balance and recipient via reading balances.
        // Check that c has zero balance (ensures funds were removed) and that recipient did not remain empty.
        assert(address(c).balance == 0);
    }
}

